use super::*;
fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){crate::test_allocation::observe_backing(operation)}
fn receipt(owner:&mut RetainedHistoryMessageDecode,grant:RetainedCloneGrant,born:usize,released:usize)->usize{let(received,progress)=owner.take_receipt().unwrap();assert_eq!(received,grant);assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));progress.copied_bytes}
fn close_text(mut text:Option<String>,grant:RetainedCloneGrant)->usize{if text.is_none(){return 0}let(result,born,released)=observe(||RetainedWireFieldDecode::admit_received_text(&mut text,grant).unwrap());assert_eq!((born,released),(0,0));let mut owner=result.unwrap();assert_eq!(owner.take_receipt().unwrap().1.copied_bytes,0);let(_,born,released)=observe(||owner.close_step(grant).unwrap());let(received,progress)=owner.take_receipt().unwrap();assert_eq!(received,grant);assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));assert!(owner.terminal_is_empty());released}
fn close_partial(mut partial:RetainedHistoryMessagePartial,grant:RetainedCloneGrant)->usize{let mut release=close_text(partial.code.take(),grant)+close_text(partial.message.take(),grant)+close_text(partial.pending_target.take(),grant);if partial.target.is_some(){let(result,born,released)=observe(||RetainedHistoryRecords::admit_original_index(&mut partial.target,grant).unwrap());assert_eq!((born,released),(0,0));let mut owner=result.unwrap();assert_eq!(owner.take_receipt().unwrap().1.copied_bytes,0);owner.cancel();for _ in 0..64{if owner.terminal_is_empty(){break}let mut recipient=None;let(_,born,released)=if owner.records().is_empty(){observe(||owner.close_step(grant).unwrap())}else{observe(||owner.take_original_into(&mut recipient,grant).unwrap())};let(received,progress)=owner.take_receipt().unwrap();assert_eq!(received,grant);assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!(progress.copied_bytes,0);release+=released;release+=close_text(recipient,grant);}assert!(owner.terminal_is_empty());}release}
fn cancel_message(owner:&mut RetainedHistoryMessageDecode,source:&[u8],grant:RetainedCloneGrant)->usize{owner.cancel();let mut release=0;for _ in 0..64{if owner.terminal_is_empty(){return release}let mut recipient=None;let(_,born,released)=if owner.partial_is_receivable(){observe(||owner.take_partial_into(&mut recipient,grant).unwrap())}else{let demand=owner.demands(source,&[],grant.maximum_copy_bytes).unwrap();for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:demand.depth-1,..grant}]{let(step,born,released)=observe(||owner.close_step(source,&[],denied).unwrap());assert_eq!(step,RetainedHistoryMessageDecodeStep::Blocked);assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none());}if demand.release_bytes>0{let(step,born,released)=observe(||owner.close_step(source,&[],RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant}).unwrap());assert_eq!(step,RetainedHistoryMessageDecodeStep::Blocked);assert_eq!((born,released),(0,0));}observe(||owner.close_step(source,&[],grant).unwrap())};assert_eq!(receipt(owner,grant,born,released),0);release+=released;if let Some(partial)=recipient{release+=close_partial(partial,grant)}}panic!("original message close did not terminate")}
#[test]
fn original_history_message_native_targets_keep_partial_receiving_and_physical_receipts(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["grant"];let n=|key:&str|p[key].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};
 for value in law["messages"].as_array().unwrap(){let source:Vec<u8>=value["wireHex"].as_str().unwrap().as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect();let mut dictionary=RetainedSourceDictionary::new(&source);
  for cancellation in[0,1,3,7,16,31,256]{for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(owner,born,released)=observe(||RetainedHistoryMessageDecode::admit(&source,(0,source.len()),denied).unwrap());assert!(owner.is_none());assert_eq!((born,released),(0,0));}let(result,born,released)=observe(||RetainedHistoryMessageDecode::admit(&source,(0,source.len()),grant).unwrap());assert_eq!((born,released),(0,0));let mut owner=result.unwrap();assert_eq!(receipt(&mut owner,grant,born,released),0);let changed=source.clone();assert!(owner.demands(&changed,&[],grant.maximum_copy_bytes).is_err());let(mut births,mut releases,mut copied)=(0,0,0);
   for _ in 0..cancellation{if owner.is_ready(){break}let demand=owner.demands(&source,&[],grant.maximum_copy_bytes).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:demand.depth-1,..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}].into_iter().enumerate(){if(axis==2&&demand.copy_bytes==0)||(axis==3&&demand.capacity_bytes==0)||(axis==4&&demand.release_bytes==0){continue}let(step,born,released)=observe(||owner.step(&source,&dictionary,&[],denied).unwrap());assert_eq!(step,RetainedHistoryMessageDecodeStep::Blocked);assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none());}let(_,born,released)=observe(||owner.step(&source,&dictionary,&[],grant).unwrap());births+=born;releases+=released;let(step,blocked_born,blocked_release)=observe(||owner.step(&source,&dictionary,&[],grant).unwrap());assert_eq!(step,RetainedHistoryMessageDecodeStep::Blocked);assert_eq!((blocked_born,blocked_release),(0,0));copied+=receipt(&mut owner,grant,born,released);}
   if cancellation==256{assert!(owner.is_ready());assert_eq!(owner.consumed_end(),source.len());let mut recipient=None;let(_,born,released)=observe(||owner.take_ready_into(&mut recipient,grant).unwrap());assert_eq!((born,released),(0,0));assert_eq!(receipt(&mut owner,grant,born,released),0);let message=recipient.unwrap();assert_eq!(message.level,value["level"].as_u64().unwrap()as u8);assert_eq!(message.code,value["code"].as_str().unwrap());assert_eq!(message.message,value["message"].as_str().unwrap());assert_eq!(message.target,value["target"].as_array().unwrap().iter().map(|text|text.as_str().unwrap()).collect::<Vec<_>>());assert_eq!(message.op_index,value["opIndex"].as_u64().map(|index|index as u32));assert_eq!(copied,message.code.len()+message.message.len()+message.target.iter().map(String::len).sum::<usize>());releases+=close_partial(RetainedHistoryMessagePartial{level:message.level,code:Some(message.code),message:Some(message.message),target:Some(message.target),pending_target:None,op_index:message.op_index},grant);}else{releases+=cancel_message(&mut owner,&source,grant)}assert!(owner.terminal_is_empty());assert_eq!(births,releases);let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));
  }dictionary.cancel();dictionary.close_step(&source,grant).unwrap();dictionary.take_receipt();assert!(dictionary.terminal_is_empty());
 }
 for source in[&[0,3,0][..],&[0,0,0,0,0,2][..],&[0,0,0,0,0,1,255,255,255,255,31][..]]{let mut dictionary=RetainedSourceDictionary::new(source);let mut owner=RetainedHistoryMessageDecode::admit(source,(0,source.len()),grant).unwrap().unwrap();owner.take_receipt();let mut refused=false;for _ in 0..64{match owner.step(source,&dictionary,&[],grant){Ok(_)=>{owner.take_receipt();},Err(_)=>{owner.take_receipt();refused=true;break}}}assert!(refused);cancel_message(&mut owner,source,grant);assert!(owner.terminal_is_empty());dictionary.cancel();dictionary.close_step(source,grant).unwrap();dictionary.take_receipt();assert!(dictionary.terminal_is_empty());}
 eprintln!("[DEBUG] original History messages preserve real code/message/target native buffers and exact vector reserve/publication receipts; partial cancellation uses paid child closure plus genuine field/index receivers, full5 independent denials metadata copy0 terminalDrop0");
}
